-- -------------------------------------------------------------
-- TABLA 1: costeo_platillos
-- Resumen financiero de cada platillo del menú
-- -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS costeo_platillos (
  id               INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  numero_menu      TINYINT UNSIGNED NOT NULL COMMENT 'Número de orden en el menú',
  nombre           VARCHAR(150)     NOT NULL,
  categoria        VARCHAR(80)      NOT NULL,
  porciones        TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Porciones por receta',
  precio_con_iva   DECIMAL(10,4)    DEFAULT NULL COMMENT 'Precio venta al cliente (con IVA)',
  precio_sin_iva   DECIMAL(10,4)    DEFAULT NULL,
  costo_porcion    DECIMAL(10,4)    DEFAULT NULL COMMENT 'Costo ingredientes / porciones',
  costo_subreceta  DECIMAL(10,4)    DEFAULT NULL COMMENT 'Subrecetas (pan, salsas base, etc.)',
  costo_empaque    DECIMAL(10,4)    DEFAULT NULL,
  costo_unitario   DECIMAL(10,4)    DEFAULT NULL COMMENT 'Costo total por unidad vendida',
  porcentaje_costo DECIMAL(6,4)     DEFAULT NULL COMMENT 'Costo / precio (e.g. 0.35 = 35%)',
  margen_unitario  DECIMAL(10,4)    DEFAULT NULL,
  porcentaje_margen DECIMAL(6,4)   DEFAULT NULL COMMENT 'Margen / precio (e.g. 0.65 = 65%)',
  incremento_delivery DECIMAL(6,4)  DEFAULT NULL COMMENT 'Factor adicional delivery (e.g. 0.27)',
  precio_delivery  DECIMAL(10,4)    DEFAULT NULL COMMENT 'Precio con IVA + delivery',
  precio_delivery_sin_iva DECIMAL(10,4) DEFAULT NULL,
  activo           TINYINT(1)       NOT NULL DEFAULT 1,
  ultima_actualizacion DATE          DEFAULT NULL,
  created_at       TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_numero_menu (numero_menu)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Costeo financiero de platillos - generado desde Excel Zensoci';

-- -------------------------------------------------------------
-- TABLA 2: costeo_detalle_ingredientes
-- Ingredientes, subrecetas y empaque de cada platillo
-- -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS costeo_detalle_ingredientes (
  id                   INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  costeo_platillo_id   INT UNSIGNED  NOT NULL,
  tipo                 ENUM('principal','secundario','empaque') NOT NULL DEFAULT 'principal',
  nombre_ingrediente   VARCHAR(200)  NOT NULL,
  cantidad             DECIMAL(12,4) DEFAULT NULL,
  unidad_medida        VARCHAR(40)   DEFAULT NULL,
  porcentaje_merma     DECIMAL(6,4)  DEFAULT 0,
  precio_unitario      DECIMAL(14,8) DEFAULT NULL COMMENT 'Costo neto sin IVA por unidad/gramo',
  costo_ingrediente    DECIMAL(10,4) DEFAULT NULL COMMENT 'costo total de este ingrediente en la receta',
  PRIMARY KEY (id),
  KEY fk_costeo_platillo (costeo_platillo_id),
  CONSTRAINT fk_costeo_platillo
    FOREIGN KEY (costeo_platillo_id) REFERENCES costeo_platillos (id)
    ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Detalle de ingredientes por receta de costeo';

